import React, { useState } from "react";
import ReactDOM from "react-dom";
import axios from "axios";
import debounce from "lodash.debounce"; // Установите lodash: npm install lodash.debounce

const API_URL = "https://www.googleapis.com/books/v1/volumes?q=isbn:";
const API_KEY = "ВАШ_API_КЛЮЧ"; // Добавьте ключ API

const fetchBookData = async (isbn, retryCount = 0) => {
  const cacheKey = `book_${isbn}`;
  const cachedData = localStorage.getItem(cacheKey);

  if (cachedData) {
    console.log("Используем кэшированные данные");
    return JSON.parse(cachedData);
  }

  try {
    const response = await axios.get(`${API_URL}${isbn}&key=${API_KEY}`);
    localStorage.setItem(cacheKey, JSON.stringify(response.data));
    return response.data;
  } catch (error) {
    if (error.response?.status === 429 && retryCount < 3) {
      console.warn(`Ошибка 429: слишком много запросов. Повторная попытка...`);
      await new Promise((resolve) => setTimeout(resolve, (retryCount + 1) * 2000)); // Увеличивающаяся задержка
      return fetchBookData(isbn, retryCount + 1);
    }
    console.error("Ошибка загрузки данных:", error);
    return null;
  }
};

const debouncedFetch = debounce(fetchBookData, 500); // Ограничение частоты запросов

const App = () => {
  const [isbn, setIsbn] = useState("");
  const [book, setBook] = useState(null);

  const handleSearch = async () => {
    if (!isbn) return;
    const data = await debouncedFetch(isbn);
    setBook(data);
  };

  return (
    <div>
      <h1>Поиск книг по ISBN</h1>
      <input
        type="text"
        value={isbn}
        onChange={(e) => setIsbn(e.target.value)}
        placeholder="Введите ISBN"
      />
      <button onClick={handleSearch}>Поиск</button>
      {book && <pre>{JSON.stringify(book, null, 2)}</pre>}
    </div>
  );
};

ReactDOM.render(<App />, document.getElementById("root"));
